/**
 * @summary Get expiring certifications and compliance items
 */
export const getGetExpiringComplianceUrl = () => {
  return `/api/compliance/expiring`;
};

export const getExpiringCompliance = async (
  options?: RequestInit,
): Promise<ExpiringComplianceItem[]> => {
  return customFetch<ExpiringComplianceItem[]>(getGetExpiringComplianceUrl(), {
    ...options,
    method: "GET",
  });
};

export const getGetExpiringComplianceQueryKey = () => {
  return [`/api/compliance/expiring`] as const;
};

export const getGetExpiringComplianceQueryOptions = <
  TData = Awaited<ReturnType<typeof getExpiringCompliance>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof getExpiringCompliance>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetExpiringComplianceQueryKey();

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getExpiringCompliance>>
  > = ({ signal }) => getExpiringCompliance({ signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getExpiringCompliance>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetExpiringComplianceQueryResult = NonNullable<
  Awaited<ReturnType<typeof getExpiringCompliance>>
>;
export type GetExpiringComplianceQueryError = ErrorType<unknown>;

/**
 * @summary Get expiring certifications and compliance items
 */

export function useGetExpiringCompliance<
  TData = Awaited<ReturnType<typeof getExpiringCompliance>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof getExpiringCompliance>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetExpiringComplianceQueryOptions(options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
